let injected = false;

// Injeta o sprite de ícones (hidden <svg><defs>) uma única vez no documento.
// Cada elemento de UI usa <use href="#i-KEY"> pra referenciar o símbolo certo.
export function injectIconSprite() {
  if (injected) return;
  injected = true;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('style', 'position:absolute;width:0;height:0;overflow:hidden');
  svg.setAttribute('aria-hidden', 'true');
  svg.innerHTML = `<defs>${MOODLE_SYMBOLS}${MENU_SYMBOLS}</defs>`;
  document.body.appendChild(svg);
}

// Nome antigo mantido como alias (hud.js já usava esse import).
export const injectMoodleIcons = injectIconSprite;
